; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: ti89 (TI-89 / 92+ / V200 (68000, AMS)), starts in turbo mode
; ============================================================

			org 0

;## ntc_md_vectors ntc_ti89_boot
; (the 68k backend requires this section be named ntc_md_vectors - the generic
;  "68k start" slot. On AMS there is no program-owned vector table; this is just
;  the entry. ;!!TI89? the real AMS nostub header/reloc goes here - stubbed.)
			bra ntc_ti89_boot

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)
NTC_RS		macro			; the real stack: the thread position kept in ntc_ip
			move.l sp, ntc_ip
			movea.l ntc_csp, sp
			endm
NTC_TS		macro			; back to the thread
			movea.l ntc_ip, sp
			endm

ntc_start:
			move.l sp, ntc_csp		; the real stack (the library's jsr calls)
			lea main_thread, sp
			rts

; ============================================================
; Main Thread
; ============================================================

main_thread:

			; 14: Cls
			dc.l kw_cls

			; 15: Print "VB self test 11"
			dc.l kw_printstrvar, str0
			dc.l kw_printnl

			; 18: Chk Add3(10), 13
			dc.l fn_add3, lit_10, var_add3_add3
			dc.l kw_vtov, var_add3_add3, tmp0
			dc.l p_chk_c, tmp0, lit_13

			; 19: a = 20
			dc.l kw_ltov, 20, var_a

			; 20: Chk Add3(a), 23
			dc.l fn_add3, var_a, var_add3_add3
			dc.l kw_vtov, var_add3_add3, tmp0
			dc.l p_chk_c, tmp0, lit_23

			; 21: Chk Add3(a * 2) + Add3(1), 47
			dc.l kw_2x, var_a, tmp0
			dc.l fn_add3, tmp0, var_add3_add3
			dc.l kw_vtov, var_add3_add3, tmp0
			dc.l fn_add3, lit_1, var_add3_add3
			dc.l kw_vtov, var_add3_add3, tmp1
			dc.l kw_add, tmp0, tmp1, tmp0
			dc.l p_chk_c, tmp0, lit_47

			; 22: Chk Add3(Add3(Add3(0))), 9
			dc.l fn_add3, lit_0, var_add3_add3
			dc.l kw_vtov, var_add3_add3, tmp0
			dc.l fn_add3, tmp0, var_add3_add3
			dc.l kw_vtov, var_add3_add3, tmp0
			dc.l fn_add3, tmp0, var_add3_add3
			dc.l kw_vtov, var_add3_add3, tmp0
			dc.l p_chk_c, tmp0, lit_9

			; 25: a = Add3(5)
			dc.l fn_add3, lit_5, var_a

			; 26: Chk a, 8
			dc.l p_chk_c, var_a, lit_8

			; 27: a = Add3(a)
			dc.l fn_add3, var_a, var_add3_add3
			dc.l kw_vtov, var_add3_add3, var_a

			; 28: Chk a, 11
			dc.l p_chk_c, var_a, lit_11

			; 31: Chk AddXY(7, 8), 15
			dc.l fn_addxy, lit_7, lit_8, var_addxy_addxy
			dc.l kw_vtov, var_addxy_addxy, tmp0
			dc.l p_chk_c, tmp0, lit_15

			; 32: b = AddXY(a, 5) * 2
			dc.l fn_addxy, var_a, lit_5, var_addxy_addxy
			dc.l kw_vtov, var_addxy_addxy, tmp0
			dc.l kw_2x, tmp0, var_b

			; 33: Chk b, 32
			dc.l p_chk_c, var_b, lit_32

			; 36: c = 41
			dc.l kw_ltov, 41, var_c

			; 37: Inc c
			dc.l fn_inc, var_c

			; 38: Chk c, 42
			dc.l p_chk_c, var_c, lit_42

			; 39: Inc c
			dc.l fn_inc, var_c

			; 40: Inc c
			dc.l fn_inc, var_c

			; 41: Chk c, 44
			dc.l p_chk_c, var_c, lit_44

			; 44: s = "hello"
			dc.l kw_strcpy, var_s, str1

			; 45: UpFirst s
			dc.l fn_upfirst, var_s

			; 46: Chk Asc(s), 72
			dc.l kw_strasc, var_s, tmp0
			dc.l p_chk_c, tmp0, lit_72

			; 47: Chk Len(s), 5
			dc.l kw_strlen, var_s, tmp0
			dc.l p_chk_c, tmp0, lit_5

			; 50: n = Big(3)
			dc.l fn_big, lit_3, var_n

			; 51: Chk n \ 65536, 3
			dc.l kw_l_div, var_n, llit_65536, ltmp0
			dc.l kw_l_ltoi, ltmp0, tmp0
			dc.l p_chk_c, tmp0, lit_3

			; 52: Chk n Mod 65536, 0
			dc.l kw_l_mod, var_n, llit_65536, ltmp0
			dc.l kw_l_ltoi, ltmp0, tmp0
			dc.l p_chk_c, tmp0, lit_0

			; 55: Chk AddC(1), 4
			dc.l fn_addc, lit_1, var_addc_addc
			dc.l kw_vtov, var_addc_addc, tmp0
			dc.l p_chk_c, tmp0, lit_4

			; 58: Chk Twice(21), 42
			dc.l p_twice_c, lit_21
			dc.l kw_vtov, var_twice_twice, tmp0
			dc.l p_chk_c, tmp0, lit_42

			; 61: c = 0
			dc.l kw_ztov, var_c

			; 62: For i = 1 To 50
			dc.l kw_ltov, 1, var_i
for1_t:

			; 63: Inc c
			dc.l fn_inc, var_c

			; 64: Next
			dc.l kw_next1l, var_i, 50, for1_t
for1_e:

			; 65: Chk c, 50
			dc.l p_chk_c, var_c, lit_50

			; 67: Print
			dc.l kw_printnl

			; 68: Print t; " tests, "; bad; " failed"
			dc.l kw_printint, var_t
			dc.l kw_printstrvar, str2
			dc.l kw_printint, var_bad
			dc.l kw_printstrvar, str3
			dc.l kw_printnl

			; 69: End
			dc.l kw_printnl0
			dc.l kw_printstrvar, str4
			dc.l kw_waitkey
			dc.l kw_stop

; ============================================================
; sub chk (turbo mode)
; ============================================================

p_chk:

			; 72: t = t + 1
			dc.l kw_inc, var_t

			; 73: Print t; ":";
			dc.l kw_printint, var_t
			dc.l kw_printstrvar, str5

			; 74: If got = want Then
			dc.l kw_cpeqvv, var_chk_got, var_chk_want
			dc.l kw_goto_iffalse, if2_1

			; 75: Print "ok ";
			dc.l kw_printstrvar, str6

			; 76: Else
			dc.l if2_e_go
if2_1:

			; 77: Print "FAIL("; got; ") ";
			dc.l kw_printstrvar, str7
			dc.l kw_printint, var_chk_got
			dc.l kw_printstrvar, str8

			; 78: bad = bad + 1
			dc.l kw_inc, var_bad

			; 79: End If
if2_e:
			dc.l p_chk_r

; ============================================================
; function twice (turbo mode)
; ============================================================

p_twice:

			; 177: #asm
			dc.l asm_0_177
			dc.l p_twice_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

if2_e_go:			lea if2_e, sp
			rts

p_chk_c:		; call chk
			movea.l (sp)+, a0		; got
			move.w (a0), var_chk_got
			movea.l (sp)+, a0		; want
			move.w (a0), var_chk_want
			move.l sp, p_chk_rs
			lea p_chk, sp
			rts
p_chk_r:		; end of chk
			movea.l p_chk_rs, sp
			rts
p_twice_c:		; call twice
			movea.l (sp)+, a0		; x
			move.w (a0), var_twice_x
			clr.w var_twice_twice
			move.l sp, p_twice_rs
			lea p_twice, sp
			rts
p_twice_r:		; end of twice
			movea.l p_twice_rs, sp
			rts

; ============================================================
; Inline assembly (#asm ... #endasm)
; ============================================================

fn_add3:		; function add3 (asm keyword), main.bas line 83
    pop hl          ; address of x [84]
    ld e,(hl)		; main.bas 85
    inc hl		; main.bas 86
    ld d,(hl)		; main.bas 87
    inc de		; main.bas 88
    inc de		; main.bas 89
    inc de		; main.bas 90
    pop hl          ; address of the result [91]
    ld (hl),e		; main.bas 92
    inc hl		; main.bas 93
    ld (hl),d		; main.bas 94
			rts			; end of #asm

fn_addxy:		; function addxy (asm keyword), main.bas line 99
    pop hl          ; x [100]
    ld e,(hl)		; main.bas 101
    inc hl		; main.bas 102
    ld d,(hl)		; main.bas 103
    pop hl          ; y [104]
    ld a,(hl)		; main.bas 105
    inc hl		; main.bas 106
    ld h,(hl)		; main.bas 107
    ld l,a		; main.bas 108
    add hl,de		; main.bas 109
    ex de,hl		; main.bas 110
    pop hl          ; result [111]
    ld (hl),e		; main.bas 112
    inc hl		; main.bas 113
    ld (hl),d		; main.bas 114
			rts			; end of #asm

fn_inc:		; sub inc (asm keyword), main.bas line 119
    pop hl          ; address of v (ByRef: write through it) [120]
    inc (hl)		; main.bas 121
    jr nz,fn_inc_done		; main.bas 122
    inc hl		; main.bas 123
    inc (hl)		; main.bas 124
fn_inc_done:		; main.bas 125
			rts			; end of #asm

fn_upfirst:		; sub upfirst (asm keyword), main.bas line 130
    pop hl          ; the string itself (0 terminated) [131]
    ld a,(hl)		; main.bas 132
    cp 'a'		; main.bas 133
    ret c		; main.bas 134
    cp 'z'+1		; main.bas 135
    ret nc		; main.bas 136
    sub 32		; main.bas 137
    ld (hl),a		; main.bas 138
			rts			; end of #asm

fn_big:		; function big (asm keyword), main.bas line 143
    pop hl          ; hi [144]
    ld e,(hl)		; main.bas 145
    inc hl		; main.bas 146
    ld d,(hl)		; main.bas 147
    pop hl          ; result: 4 bytes, low word first [148]
    xor a		; main.bas 149
    ld (hl),a		; main.bas 150
    inc hl		; main.bas 151
    ld (hl),a		; main.bas 152
    inc hl		; main.bas 153
    ld (hl),e		; main.bas 154
    inc hl		; main.bas 155
    ld (hl),d		; main.bas 156
			rts			; end of #asm

fn_addc:		; function addc (asm keyword), main.bas line 161
    pop hl		; main.bas 162
    ld e,(hl)		; main.bas 163
    inc hl		; main.bas 164
    ld d,(hl)		; main.bas 165
    ld hl,3		; main.bas 166
    add hl,de		; main.bas 167
    ex de,hl		; main.bas 168
    pop hl		; main.bas 169
    ld (hl),e		; main.bas 170
    inc hl		; main.bas 171
    ld (hl),d		; main.bas 172
			rts			; end of #asm

asm_0_177:		; #asm, main.bas line 177
    ld hl,(var_twice_x)		; main.bas 178
    add hl,hl		; main.bas 179
    ld (var_twice_twice),hl		; main.bas 180
			rts			; end of #asm


